__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),e.getSuggestions=function(o,n){return('couple'===n?s:'family'===n?u:t)[o]};const s={loved:['Si tu doutes de mon amour, relis ceci : je t\u2019aime, tout simplement, tous les jours.','Ce que j\u2019aime le plus chez toi, c\u2019est\u2026','Le jour o\xf9 j\u2019ai su que c\u2019\xe9tait toi, c\u2019\xe9tait\u2026'],sad:['Je sais que c\u2019est dur en ce moment. Tu n\u2019es pas seul\xb7e, je suis l\xe0.','Tu as le droit d\u2019\xeatre triste. Prends le temps qu\u2019il te faut.','Pense \xe0 ce souvenir avec moi : \u2026'],stressed:['Respire. Une chose \xe0 la fois. Je crois en toi.','Tu as d\xe9j\xe0 travers\xe9 tellement de choses, tu vas y arriver.','Ce soir, on se fait un moment rien qu\u2019\xe0 nous.'],lonely:['M\xeame loin, je pense \xe0 toi plus souvent que tu ne l\u2019imagines.','Ferme les yeux : je te prends dans mes bras.','Appelle-moi, m\xeame pour rien. J\u2019ai toujours envie de t\u2019entendre.'],exhausted:['Tu en fais tellement. Tu as le droit de t\u2019arr\xeater un peu.','Va te reposer, je m\u2019occupe du reste.','Je suis fier\xb7\xe8re de tout ce que tu donnes.'],angry:['Je sais que je t\u2019ai peut-\xeatre bless\xe9\xb7e. Je t\u2019aime, m\xeame quand on n\u2019est pas d\u2019accord.','Quand tu seras pr\xeat\xb7e, je serai l\xe0 pour en parler.','Une dispute ne changera jamais ce que je ressens pour toi.'],doubt:['Tu es bien plus capable que tu ne le crois.','Si tu te voyais avec mes yeux, tu ne douterais jamais.','Voici trois choses que j\u2019admire chez toi : \u2026'],bad_day:['Cette journ\xe9e ne te d\xe9finit pas. Demain est une nouvelle page.','Tu m\xe9rites un c\xe2lin, un plaid et ton plat pr\xe9f\xe9r\xe9.','Raconte-moi tout ce soir, je t\u2019\xe9couterai.'],sleepless:['Imagine-moi juste \xe0 c\xf4t\xe9 de toi. Respire doucement avec moi.','Tout ira bien. Ferme les yeux, je veille sur toi.','Pense \xe0 notre prochain week-end ensemble\u2026'],smile:['Tu te souviens de la fois o\xf9\u2026 ? Je ris encore en y pensant.','Ton sourire est ma chose pr\xe9f\xe9r\xe9e au monde.','Petite mission : va te regarder dans le miroir et souris. Voil\xe0, tu es magnifique.']},t={loved:['Je ne te le dis pas assez : tu comptes \xe9norm\xe9ment pour moi.','Ma vie serait beaucoup moins dr\xf4le sans toi.','Merci d\u2019\xeatre toi, et d\u2019\xeatre l\xe0 depuis tout ce temps.'],sad:['Je suis l\xe0. Pour parler, ou juste pour \xeatre \xe0 c\xf4t\xe9.','Tu as le droit d\u2019aller mal. On traverse \xe7a ensemble.','Tu te souviens de\u2026 ? On a d\xe9j\xe0 surmont\xe9 pire, toi et moi.'],stressed:['Respire. Tu as g\xe9r\xe9 bien pire que \xe7a.','Une chose \xe0 la fois. Et apr\xe8s, on f\xeate \xe7a.','Je crois en toi, m\xeame quand tu n\u2019y crois plus.'],lonely:['Tu n\u2019es jamais seul\xb7e : j\u2019ai toujours un message ou un appel pour toi.','\xc9cris-moi, m\xeame \xe0 3 h du matin.','On se fait un moment bient\xf4t ? C\u2019est moi qui invite.'],exhausted:['Pause obligatoire. Ordre de ton ami\xb7e.','Tu donnes beaucoup aux autres. Garde un peu pour toi.','Repose-toi, le monde peut attendre une soir\xe9e.'],angry:['On n\u2019est pas toujours d\u2019accord, mais tu restes une personne essentielle pour moi.','Quand tu voudras en parler, je serai l\xe0.','Notre amiti\xe9 vaut bien plus qu\u2019un d\xe9saccord.'],doubt:['Tu es une des personnes les plus fortes que je connaisse.','Voici ce que j\u2019admire chez toi : \u2026','Je te vois r\xe9ussir, m\xeame quand tu ne le vois pas.'],bad_day:['Journ\xe9e pourrie ? Demain, on la remplace par une meilleure.','Raconte-moi tout, je prends le temps.','Je t\u2019envoie un c\xe2lin d\u2019ami\xb7e, le plus fort possible.'],sleepless:['Pense \xe0 notre meilleur fou rire. \xc7a va mieux ?','Respire doucement. Tout ira bien demain.','Si tu ne dors pas, \xe9cris-moi. Je r\xe9pondrai d\xe8s que je peux.'],smile:['Tu te souviens de la fois o\xf9\u2026 ? J\u2019en ris encore.','Petit rappel : tu es g\xe9nial\xb7e, et je ne suis pas objectif\xb7ve.','Souris : quelqu\u2019un pense \xe0 toi en ce moment m\xeame.']},u={loved:['Je t\u2019aime, m\xeame si je ne le dis pas assez souvent.','Je suis tellement fier\xb7\xe8re de faire partie de ta famille.','Merci pour tout ce que tu m\u2019as donn\xe9.'],sad:['Je suis l\xe0 pour toi, comme toujours.','Tu peux tout me dire, je t\u2019\xe9couterai sans juger.','Pense \xe0 ce souvenir de famille : \u2026'],stressed:['Respire. Tu as toujours su faire face, je te connais.','Une chose \xe0 la fois. Et n\u2019oublie pas que tu peux compter sur moi.','Je crois en toi, depuis toujours.'],lonely:['M\xeame loin, tu fais toujours partie de mes pens\xe9es.','Appelle-moi quand tu veux. J\u2019aime entendre ta voix.','Tu n\u2019es jamais seul\xb7e : ta famille est l\xe0.'],exhausted:['Prends soin de toi, c\u2019est important pour moi.','Tu as le droit de te reposer. Vraiment.','Je suis fier\xb7\xe8re de tout ce que tu fais.'],angry:['On ne se comprend pas toujours, mais je t\u2019aime.','Quand tu seras pr\xeat\xb7e, parlons-en calmement.','Rien ne changera ce que tu repr\xe9sentes pour moi.'],doubt:['Je t\u2019ai vu grandir et devenir quelqu\u2019un de formidable.','Voici ce que j\u2019admire chez toi : \u2026','Tu es capable de bien plus que tu ne le crois.'],bad_day:['Demain sera une meilleure journ\xe9e, j\u2019en suis s\xfbr\xb7e.','Je t\u2019envoie toute ma tendresse.','Raconte-moi ta journ\xe9e, j\u2019ai le temps.'],sleepless:['Ferme les yeux et pense \xe0 un bon souvenir ensemble.','Tout ira bien. Je pense fort \xe0 toi.','Respire doucement, comme quand tu \xe9tais petit\xb7e.'],smile:['Tu te souviens de\u2026 ? On en rit encore en famille.','Ton sourire illumine toujours la maison.','Je pense \xe0 toi et \xe7a me fait sourire.']}},845,[]);